<section class="content-header"><h1><i class="fa fa-road"></i> Ventas por ruta</h1></section><section class="content"><div class="box box-primary no-print"><div class="box-body"><form method="get" class="form-inline"><label>Desde</label> <input type="date" name="desde" class="form-control" value="<?php echo html_escape($filtros['desde']); ?>"> <label>Hasta</label> <input type="date" name="hasta" class="form-control" value="<?php echo html_escape($filtros['hasta']); ?>"> <select name="ruta_id" class="form-control"><option value="0">Todas las rutas</option><?php foreach($listas['rutas'] as $r): ?><option value="<?php echo $r['ruta_id']; ?>" <?php echo $filtros['ruta_id']==$r['ruta_id']?'selected':''; ?>><?php echo html_escape($r['ruta_nombre']); ?></option><?php endforeach; ?></select> <select name="vehiculo_id" class="form-control"><option value="0">Todos los vehículos</option><?php foreach($listas['vehiculos'] as $v): ?><option value="<?php echo $v['vehiculo_id']; ?>" <?php echo $filtros['vehiculo_id']==$v['vehiculo_id']?'selected':''; ?>><?php echo html_escape($v['vehiculo_placa'].' '.$v['vehiculo_marca']); ?></option><?php endforeach; ?></select> <button class="btn btn-primary"><i class="fa fa-search"></i> Generar</button></form></div></div><div class="box"><div class="box-header"><h3 class="box-title">Resumen comercial por ruta</h3><div class="pull-right no-print"><button onclick="window.print()" class="btn btn-default btn-sm"><i class="fa fa-print"></i> Imprimir</button> <a class="btn btn-success btn-sm" href="<?php echo site_url('reporte_ventas_ruta/csv').'?'.http_build_query($filtros); ?>"><i class="fa fa-file-excel-o"></i> Excel/CSV</a></div></div><div class="box-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Ruta</th><th class="text-right">Viajes</th><th class="text-right">Pasajeros</th><th class="text-right">Ingreso</th><th class="text-right">Ingreso/Pasajero</th><th class="text-right">Pasajeros/Viaje</th></tr></thead><tbody><?php $tv=$tp=$ti=0; foreach($filas as $r): $tv+=$r['viajes'];$tp+=$r['pasajeros'];$ti+=$r['ingreso']; ?><tr><td><b><?php echo html_escape($r['ruta']); ?></b></td><td class="text-right"><?php echo number_format($r['viajes'],0,',','.'); ?></td><td class="text-right"><?php echo number_format($r['pasajeros'],0,',','.'); ?></td><td class="text-right"><b>Bs <?php echo number_format($r['ingreso'],2,',','.'); ?></b></td><td class="text-right">Bs <?php echo number_format($r['ingreso_pasajero'],2,',','.'); ?></td><td class="text-right"><?php echo number_format($r['pasajeros_viaje'],1,',','.'); ?></td></tr><?php endforeach; ?></tbody><tfoot><tr class="info"><th>TOTAL</th><th class="text-right"><?php echo number_format($tv,0,',','.'); ?></th><th class="text-right"><?php echo number_format($tp,0,',','.'); ?></th><th class="text-right">Bs <?php echo number_format($ti,2,',','.'); ?></th><th class="text-right">Bs <?php echo $tp>0?number_format($ti/$tp,2,',','.'):'0,00'; ?></th><th class="text-right"><?php echo $tv>0?number_format($tp/$tv,1,',','.'):'0,0'; ?></th></tr></tfoot></table></div></div></div></section><style media="print">.no-print,.main-header,.main-sidebar,.content-header,.main-footer{display:none!important}.content-wrapper{margin-left:0!important}.content{padding:0!important}</style>